INSERT INTO feature VALUES('rap-subscriptions','editor','Durable toolset subscriptions','rap-toolset','implemented','uncommon','mainstream editors','`subscribe_diagnostics` follows the frame of a document, and `subscribe_account` follows the account card of a declaration by its name. The manifest offers both, and `tools/list` does not. The worker writes each subscription to the table of the workspace before the result that confirms it with `subscription: true`. After each admission that changes the card, one `subscription_event` carries the URI, the name and the card, with the version beside them. The hub''s build with the `instrument` feature offers `subscribe_activity` too. While a row follows it, the hub folds the activity ring, and the row keeps the events that its runtime did not take, 4096 at most, and counts each drop. It has one state in flight at most, keyed by the run of the toolset and the sequence number of its last event. The table is one file under the XDG state directory, written whole through a rename, and absent when it has no row. A later hub resumes each row and sends no state of a version that the runtime took. `/cancel_tool_call` and `/close_thread` drop their rows and answer `200`.','surface-agentic surface-driver','crates/surface-agentic/src/rap.rs crates/surface-agentic/src/rap/subscriptions.rs crates/surface-agentic/src/rap/activity/tests.rs',NULL,'#6341 #6450');
